using CommerceErp.Core;
using static CommerceErp.Infrastructure.CommerceDatabase;
namespace CommerceErp.Infrastructure;
public sealed partial class MasterDataService
{
    private static List<SkuMapping> ReadMaps(DbSession db,SkuMapping? key=null,int? limit=null)=>db.Query("SELECT m.Platform,m.ShopId,m.ProductId,m.VariantId,m.SkuId,m.MultiplierUnits,m.Version,COALESCE(x.Enabled,1) FROM SkuMappings m LEFT JOIN MasterMappingState x ON x.TenantId=m.TenantId AND x.Platform=m.Platform AND x.ShopId=m.ShopId AND x.ProductId=m.ProductId AND x.VariantId=m.VariantId WHERE m.TenantId=$t AND ($shop IS NULL OR (m.Platform=$p AND m.ShopId=$shop AND m.ProductId=$product AND m.VariantId=$variant))"+SecurityContext.ShopFilter("m")+" ORDER BY m.Platform,m.ShopId,m.ProductId,m.VariantId"+(limit is null?"":db.Limit(limit.Value)),r=>new SkuMapping(Tenant(db),Enum.Parse<Platform>(r.GetString(0)),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),BusinessUnits.FromQuantity(r.GetInt64(5)),r.GetInt32(6),r.GetInt64(7)==1),("t",Tenant(db)),("shop",key?.ShopId),("p",key?.Platform.ToString()),("product",key?.PlatformProductId),("variant",key?.PlatformSkuId));
    private static void IncludeSku(DbSession db,List<SkuProfile> skus,string id){if(skus.Any(s=>s.Id==id))return;var row=Skus(db,id:id).SingleOrDefault();if(row is null)return;skus.Add(row);foreach(var component in row.Components)IncludeSku(db,skus,component.SkuId);}
    public MasterSnapshot Context()=>database.Read(BuildContext);
    internal static MasterSnapshot BuildContext(DbSession db){var rows=Skus(db,limit:50);var maps=ReadMaps(db,limit:50);foreach(var m in maps)IncludeSku(db,rows,m.InternalSkuId);foreach(var sku in rows.ToList())foreach(var c in sku.Components)IncludeSku(db,rows,c.SkuId);return new MasterSnapshot(Profile(db),rows,maps,[]);}
    public MasterLookup Lookup(MasterLookupRequest r)=>database.Read(db=>{if(r.Codes is null||r.Ids is null||r.Keys is null||r.Codes.Count+r.Ids.Count+r.Keys.Count>200)throw new BusinessRuleException("每次最多解析200项。");var rows=new List<SkuProfile>();foreach(var code in r.Codes.Distinct()){Text(code,"SKU编码");var sku=Skus(db,code:code).SingleOrDefault();if(sku is not null)IncludeSku(db,rows,sku.Id);}foreach(var id in r.Ids.Distinct()){Text(id,"SKU标识");IncludeSku(db,rows,id);}var maps=new List<SkuMapping>();foreach(var key in r.Keys){if(key is null)throw new BusinessRuleException("映射键不能为空。");maps.AddRange(ReadMaps(db,key));}foreach(var m in maps)IncludeSku(db,rows,m.InternalSkuId);return new MasterLookup(rows,maps);});
    public MasterPage<ProductChoice> Products(string shop,string search="",int page=1,int size=50)=>database.Read(db=>{Paging(page,size,search);var from=" FROM SkuMappings m JOIN Skus sk ON sk.Id=m.SkuId AND sk.Enabled=1 JOIN MasterShopData sh ON sh.ShopId=m.ShopId AND sh.Enabled=1 LEFT JOIN MasterMappingState x ON x.TenantId=m.TenantId AND x.Platform=m.Platform AND x.ShopId=m.ShopId AND x.ProductId=m.ProductId AND x.VariantId=m.VariantId WHERE m.TenantId=$t AND m.ShopId=$shop AND COALESCE(x.Enabled,1)=1 AND (CHARINDEX($q,sk.Code)>0 OR CHARINDEX($q,sk.Name)>0 OR CHARINDEX($q,m.ProductId)>0 OR CHARINDEX($q,m.VariantId)>0)"+SecurityContext.ShopFilter("m");var args=new (string,object?)[]{("t",Tenant(db)),("shop",shop),("q",search),("offset",(page-1)*size),("limit",size)};var total=db.Scalar<int>("SELECT COUNT(*)"+from,args);var rows=db.Query("SELECT sk.Code,sk.Name,m.Platform,m.ProductId,m.VariantId,m.SkuId,m.MultiplierUnits,m.Version"+from+" ORDER BY sk.Code,m.ProductId,m.VariantId"+db.Page,r=>new ProductChoice(r.GetString(0)+" · "+r.GetString(1)+" / "+r.GetString(3)+" / "+r.GetString(4),new(Tenant(db),Enum.Parse<Platform>(r.GetString(2)),shop,r.GetString(3),r.GetString(4),r.GetString(5),BusinessUnits.FromQuantity(r.GetInt64(6)),r.GetInt32(7))),args);return new MasterPage<ProductChoice>(rows,total,page,size);});
}
